head.script:
scwin.init = function() {
    var jsonData = [];
    for (var i = 0; i < 550; i++) {
        var rowData = {
            col2: i,
            col3: i + 'click'
        }
        jsonData.push(rowData);
    }
    dataList1.setJSON(jsonData);
};
scwin.gridView1_onrowindexchange = function(row, oldRow) {
    localStorage.setItem("oldRow", oldRow);
    //alert(oldRow);
    console.log('oldRow :: ' + oldRow);
};
scwin.gridView1_oncellclick = function(row, col) {
    console.log('oncell : ' + row + col);
};
scwin.trigger2_onclick = function(e) {
    var options = {
        fileName: "test.cell",
        headerFontName: "휴먼아미체",
        footerFontName: "궁서체",
        useStyle: 'true'
    };
    gridView1.advancedExcelDownload(options);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 그리드뷰에서 마우스 스크롤을 아래로 이동한다.(끝까지 이동 시 2번 스크롤이동)
    //1. After running the sample file, move the mouse scroll down in the grid view (scroll 2 times to the end)
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 3000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 6000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 9000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 11000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_4_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('oldRow') == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
